import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define WARP_SIZE 32

__global__ void matvec_kernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float* __restrict__ C,
                               int M, int K) {
    int row = blockIdx.x;
    if (row >= M) return;

    const float4* A_row = reinterpret_cast<const float4*>(A + (size_t)row * K);
    const float4* B_vec = reinterpret_cast<const float4*>(B);

    int K4 = K / 4;
    float sum = 0.0f;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    int i = tid;
    // Unrolled loop (factor 4) for better ILP / memory-level parallelism
    #pragma unroll 4
    for (; i + 3 * nthreads < K4; i += 4 * nthreads) {
        float4 a0 = A_row[i];
        float4 b0 = B_vec[i];
        float4 a1 = A_row[i + nthreads];
        float4 b1 = B_vec[i + nthreads];
        float4 a2 = A_row[i + 2 * nthreads];
        float4 b2 = B_vec[i + 2 * nthreads];
        float4 a3 = A_row[i + 3 * nthreads];
        float4 b3 = B_vec[i + 3 * nthreads];
        sum += a0.x * b0.x + a0.y * b0.y + a0.z * b0.z + a0.w * b0.w;
        sum += a1.x * b1.x + a1.y * b1.y + a1.z * b1.z + a1.w * b1.w;
        sum += a2.x * b2.x + a2.y * b2.y + a2.z * b2.z + a2.w * b2.w;
        sum += a3.x * b3.x + a3.y * b3.y + a3.z * b3.z + a3.w * b3.w;
    }
    for (; i < K4; i += nthreads) {
        float4 a = A_row[i];
        float4 b = B_vec[i];
        sum += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
    }

    // handle remainder (K not divisible by 4) - not needed here since K div by 4
    int rem_start = K4 * 4;
    for (int i = rem_start + threadIdx.x; i < K; i += blockDim.x) {
        sum += A[(size_t)row * K + i] * B[i];
    }

    // warp-level reduction
    unsigned mask = 0xffffffff;
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset);
    }

    __shared__ float warp_sums[32];
    int lane = threadIdx.x % WARP_SIZE;
    int warp_id = threadIdx.x / WARP_SIZE;

    if (lane == 0) {
        warp_sums[warp_id] = sum;
    }
    __syncthreads();

    int num_warps = (blockDim.x + WARP_SIZE - 1) / WARP_SIZE;
    if (warp_id == 0) {
        float val = (lane < num_warps) ? warp_sums[lane] : 0.0f;
        for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
            val += __shfl_down_sync(mask, val, offset);
        }
        if (lane == 0) {
            C[row] = val;
        }
    }
}

torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B) {
    A = A.contiguous();
    B = B.contiguous();

    int M = A.size(0);
    int K = A.size(1);

    auto C = torch::empty({M, 1}, A.options());

    const int threads = 512;
    const int blocks = M;

    matvec_kernel<<<blocks, threads>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );

    return C;
}
"""

cpp_source = r"""
torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B);
"""

matvec_module = load_inline(
    name="matvec_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matvec_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matvec = matvec_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        A = A.cuda().float()
        B = B.cuda().float()
        return self.matvec.matvec_cuda(A, B)


M = 256 * 8  # 2048
K = 131072 * 8  # 1048576


def get_inputs():
    A = torch.rand(M, K)
    B = torch.rand(K, 1)
    return [A, B]


def get_init_inputs():
    return []

